QuestGuidance.Register("en",302,{
[9633]="70015E2B\n1\tDefeat half-orcs at Pembar (total: 15)\tHalf-orcs can be found in Pembar, north-east of Echad Eregion. Lengliel has asked you to defeat a number of Saruman's half-orcs and investigate their purpose at Pembar.\n2\tTalk to Lengliel at Echad Eregion\tLengliel is at Echad Eregion, south-west of Pembar. You should return to Lengliel with news of your success.\n",
[9634]="700544B3\n1\tCollect Cargûl pendants (total: 6)\tCargûl can be found in the Circle of Sorrow in Minas Morgul. You should collect pendants from them as they fall.\n2\tBring the Cargûl pendants to Damrod in Barad Orhant\tDamrod can be found in Barad Orhant in Minas Morgul. You should bring the pendants collected from the Cargûl to Damrod.\n",
[9635]="70033966\n1\tDeliver the bent wings to a collection box\030Collect bent wings (total: 10)\tYou have accepted a task to acquire bent wings.\n",
[9636]="7003395E\n1\tDeliver the damaged ears to a collection box\030Collect damaged ears (total: 10)\tYou have accepted a task to acquire damaged ears.\n",
[9637]="70033961\n1\tDeliver the mossy branches to a collection box\030Collect mossy branches (total: 10)\tYou have accepted a task to acquire mossy branches.\n",
[9638]="70033959\n1\tDeliver the ornate sword sheaths to a collection box\030Collect ornate sword sheaths (total: 10)\tYou have accepted a task to acquire ornate sword sheaths.\n",
[9639]="7003395A\n1\tDeliver the ripped cloaks to a collection box\030Collect ripped cloaks (total: 10)\tYou have accepted a task to acquire ripped cloaks.\n",
[9640]="70033963\n1\tDeliver the slimy filth to a collection box\030Collect slimy filth (total: 10)\tYou have accepted a task to acquire slimy filth.\n",
[9641]="7003395D\n1\tDeliver the tattered skins to a collection box\030Collect tattered skins (total: 10)\tYou have accepted a task to acquire tattered skins.\n",
[9642]="7003395C\n1\tDeliver the unkempt furs to a collection box\030Collect unkempt furs (total: 10)\tYou have accepted a task to acquire unkempt furs.\n",
